(35, 35, 'ট্যুর প্লান', '1', 'Right side', 'Image', 'বান্দরবন', 'public/uploads/blog/images/1716571336859394.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">আমাদের</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">ট্যুরের প্ল্যান</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">করা</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">হয়েছিল</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">২৪/১০/২০২১</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">তারিখ</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">থেকে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">২৯/১০/২০২১</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">তারিখ</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">পর্যন্ত।</span> <o:p></o:p></p><p>\r\n\r\n</p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">আমরা\r\nআমদের ট্যুর প্লান নিয়ে খুব চিন্তিত ছিলাম । কারন অল্প&nbsp;&nbsp; সময়ের মধ্যে আমরা অনেক গুলো জায়গা ঘুরতে চেয়েছিলাম\r\n। আমদের&nbsp;&nbsp; প্ল্যানের মধ্যে&nbsp; জায়গাগুলো ছিল দেবতাখুম, নীলগিরি , চিম্বুক</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">পর্যটন</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">,শৈলপ্রপাত ,কক্সবাজার সমুদ্র সৈকত\r\n, মেরিন ড্রাইভ &nbsp;,ইনানী সী বীচ , মহেশখালী</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">সি</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">বিচ , হিমছড়ি</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">পাহাড়। আমাদের প্লান বাস্তবায়নে অনেক\r\nবাঁধার সম্মুখীন হতে হয়েছে আমদের সময় কম ছিল এবং&nbsp;\r\nঅনেকে অসুস্থ হয়ে পরেছিল কারন অতিরিক্ত জার্নি করার অভিজ্ঞতা ছিল নাহ।কিন্তু\r\nনানা বাঁধা&nbsp;&nbsp; আসার পরও আমদের প্লান সাকসেস হয়েছে।<o:p></o:p></span></p>', 2, 1, '2021-11-16 02:06:36', NULL),
(36, 35, 'যাত্রা  আরাম্ভ', '1', 'Right side', 'Image', 'বান্দরবন', 'public/uploads/blog/images/1716571581135720.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">২৪\r\nতারিখে</span>&nbsp; <span style=\"font-family:\r\n&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দুপুরে আমরা</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">বান্দরবানের</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">উদ্দেশ্যে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">রাজবাড়ী</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">থেকে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">রওনা হই।</span> &nbsp;<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">প্রথমে\r\nআমরা ঢাকা যাই , ঢাকা যাওয়ার জন্য আমরা প্রথমে মহেন্দ্র গাড়ি নিয়ে দৌলতদিয়া ফেরিঘাট\r\nযাই ফেরি পারাপার হয়ে পাটুরিয়া ফেরিঘাট যাই ওখান থেকে গাবতলির জন্য লোকাল বাসে উঠি।গাবতলি\r\nথেকে আমরা কল্যাণপুর যাই তারপর বান্দরবন যাওয়ার জন্য বাসে উথি। বাস জার্নি করার সময়\r\nকয়েক জনের শারীরিক অবস্থা&nbsp; খারাপ হয়ে যায়।<o:p></o:p></span></p>', 3, 1, '2021-11-16 02:10:29', NULL),
(37, 35, 'বান্দরবানের প্রথম দিন', '1', 'Left side', 'Image', 'বান্দরবন', 'public/uploads/blog/images/1716572318175382.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">২৫\r\nতারিখ</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">সকাল</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">পাঁচটায়</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">আমরা</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">বান্দরবানের&nbsp; পৌঁছাই । </span><span style=\"font-size: 1rem;\">&nbsp;</span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">আমরা</span><span style=\"font-size: 1rem;\">\r\n</span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">&nbsp;২ টা হোটেলে</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">উঠি &nbsp;একটি হোটেল\r\nহিল ভিউ&nbsp; অন্যটি হিল বার্ড। এক</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">ঘন্টা</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">সময়ের মধ্যে </span><span style=\"font-size: 1rem;\">&nbsp;</span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">সবাই\r\nচটপট</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">প্রস্তত </span><span style=\"font-size: 1rem;\">&nbsp;</span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">হয়ে\r\nযায় ।</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">আমরা</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">সকালে</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">নাস্তা</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">করে</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">বের</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">হয়ে</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">যাই</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">দেবতাখুম</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">পাহাড়ের</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">উদ্দেশ্যে</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">।</span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">পাহাড়</span><span style=\"font-size: 1rem;\">\r\n</span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">যাওয়ার</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">জন্য</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">&nbsp;চান্দের</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">গাড়িতে\r\nযাত্রা&nbsp; শুরু হয়। বান্দরবনের</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">সবকিছু</span><span style=\"font-size: 1rem;\">&nbsp; </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">যেনও\r\nপাহাড়জুড়ে</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">থাকে।</span><span style=\"font-size: 1rem;\">\r\n</span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">পাহাড়ি</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">রাস্তা</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">পাড়ি</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">দেওয়ার</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">সময়</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">মুখ</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">দিয়ে</span><span style=\"font-size: 1rem;\"> </span><b style=\"font-size: 1rem;\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">জটিল</span> </b><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">,<b>শী-রাম</b>,</span><b style=\"font-size: 1rem;\"> </b><b style=\"font-size: 1rem;\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">করা</span></b><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\"> , <b>জোশ</b> </span><span style=\"font-size: 1rem;\">&nbsp;</span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">শব্দগুলো</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">বের</span><span style=\"font-size: 1rem;\"> </span><span style=\"font-size: 1rem; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">হচ্ছিল।</span></p>', 4, 1, '2021-11-16 02:22:12', '2021-11-16 02:33:42'),
(38, 35, 'বান্দরবানের প্রথম দিন', '1', 'Right side', 'Image', 'বান্দরবন', 'public/uploads/blog/images/1716572841964020.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">কারণ</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">পাহাড়ের</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">উচু</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">হতে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">হতে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">থমকে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">যাওয়া</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">আঁকাবাঁকা</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">রাস্তা।<o:p></o:p></span></p><p>\r\n\r\n</p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দু</span>\'<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">পাশে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">ঢিবির</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">মতো</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">উঁচু</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">পাহাড়ের</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">চাদর</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">এই</span> <span style=\"font-family:\r\n&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দুই</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দৃশ্যগুলো</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">যদি</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">কোন</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">কবি</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দেখতেন</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">তিনিও হয়তো</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">&nbsp;বলতেন</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">অনিন্দ্যসুন্দর,</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">নয়নাভিরা্‌</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">মনোরম</span> ,<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">অতুলনীয়।<o:p></o:p></span></p>', 5, 1, '2021-11-16 02:30:31', NULL),
(39, 35, 'বান্দরবানের প্রথম দিন', '1', 'Left side', 'Image', 'বান্দরবন', 'public/uploads/blog/images/1716573505371153.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দেবতখুম\r\nবান্দরবান জেলা শহর থেকে ২০ কিলোমিটার দূরে রোয়াংছড়ি উপজেলার শীলবান্ধা পাড়ায় অবস্থিত।\r\nখুমের গভীরতা ৫০ থেকে ৬০ ফুট। দেবতাখুমের</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দৈর্ঘ্য</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">৬০০ফিট।<o:p></o:p></span></p>', 6, 1, '2021-11-16 02:41:04', NULL),
(40, 35, 'বান্দরবানের প্রথম দিন', '1', 'Left side', 'Image', 'বান্দরবন', 'public/uploads/blog/images/1716574195581463.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দেবতখুম\r\nযাওয়ার জন্য আমদের যেতে হয়েছিল বোয়াংছরি উপজেলার কচ্ছপতলী আর্মি কাম্পে।বোয়াংছরি\r\nথানায় প্রথমে আমদের জাতীয় পরিচয় পত্র এর ফটোকপি জমা দিতে হয়েছিল বোয়াংছরি থানায় প্রশাসনিক\r\nপ্রসেসটা অনেক কঠিন ছিল&nbsp; ১ ঘণ্টার বেশি সময়\r\nলাগে কাজটা করতে।আমদের সাথে ২ জন গাইড দিয়ে দেওয়া হল।<o:p></o:p></span></p>', 7, 1, '2021-11-16 02:52:02', NULL),
(41, 35, 'বান্দরবানের প্রথম দিন', '1', 'Right side', 'Image', 'বান্দরবন', 'public/uploads/blog/images/1716574449514545.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">অবশেষে</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">&nbsp;কচ্ছপতলী আর্মি কাম্পে পোঁছালাম । প্রশাসনিক কাজ\r\nশেষ করে অবশেষে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">আমরা</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দেবতাখুম</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">জয়</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">করার</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">জন্য ট্র্যাকিং শুরু হল।পাহাড়ে ট্র্যাকিং\r\nবরাবর রোমাঞ্চকর।পাহাড় জয় করে আমদের গন্তব্য দেবতাখুম পোঁছালাম দেখলাম দুপাশে উঁচু\r\nপাথুরে ঢাল, কলকল শব্দে বয়ে চলেছে পাহাড়ি ঝিরি।বিশাল</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">বিশাল</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">পাথর</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">এর</span> <span style=\"font-family:\r\n&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">মাঝখান</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দিয়ে</span>\r\n<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">বয়ে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">চলেছে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">ঝর্না,</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">নদীর</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">দৃশ্য</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">।<o:p></o:p></span></p>', 8, 1, '2021-11-16 02:56:04', NULL),
(42, 36, 'ইউনাইটেড হাসপাতালে ওয়েক  আপ আইসিটি  কর্তৃক তৈরিকৃত  হার্ট কপ সফটওয়্যার হস্তান্তর……', '1', 'Left side', 'Image', 'ইউনাইটেড হাসপাতালে ওয়েক  আপ আইসিটি  কর্তৃক তৈরিকৃত  হার্ট কপ সফটওয়্যার হস্তান্তর……', 'public/uploads/blog/images/1716575648440158.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><b><i><span style=\"color:red\">&nbsp;</span></i></b><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">ইউনাইটেড</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">হসপিটালের</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">কার্ডিওলোজি</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">বিভাগের</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">চিকিৎসা\r\nব্যবস্থা আরও আধুনিক ও</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">প্রযুক্তিনির্ভর</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">করার</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">জন্য </span><b style=\"font-size: 1rem;\"><i><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;;color:red\">ওয়েক</span><span style=\"color:red\">&nbsp; </span></i></b><b style=\"font-size: 1rem;\"><i><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;;color:red\">আপ আইসিটি</span><span style=\"color:red\">&nbsp; </span></i></b><b style=\"font-size: 1rem;\"><i><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;;color:red\">কর্তৃক তৈরিকৃত</span><span style=\"color:red\">&nbsp;&nbsp; </span></i></b><b style=\"font-size: 1rem;\"><i><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;;color:red\">হার্ট কপ </span><span style=\"color:red\">&nbsp;</span></i></b><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">সফটওয়্যারটি</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">ব্যবহার</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">করা</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">শুরু</span><span style=\"font-size: 10pt; line-height: 115%;\"> </span><span style=\"font-size: 10pt; line-height: 115%; font-family: &quot;Nirmala UI&quot;, &quot;sans-serif&quot;;\">করেছেন।</span></p>', 1, 1, '2021-11-16 03:15:08', '2021-11-17 03:30:53');
