(70, 35, 'কক্সবাজার প্রথম দিন', '1', 'Left side', 'Image', 'বান্দরবন  To কক্সবাজার', 'public/uploads/blog/images/1717029043693144.png', '', '', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">&nbsp;</span></p><p>\r\n\r\n</p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">২৭\r\nতারিখ সকালে </span>&nbsp;<span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">আমরা</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">সবাই</span> <span style=\"font-family:&quot;Nirmala UI&quot;,&quot;sans-serif&quot;\">&nbsp;যাই সমুদ্র স্নান করতে। আমরা সেদিন গিয়েছিলাম&nbsp; সমুদ্র সময় দেওয়ার জন্য। টানা ৬ ঘণ্টা আমরা সমুদ্র\r\nস্নান করি।আমরা সেদিন&nbsp; কেন মোবাইল ফোন নিয়ে\r\nযাই নি তাই&nbsp; কেও ছবি তুলতে পারে নি। অনেক সময়\r\nজাপাজাপি করে আমরা হোটেলে ফিরে আসি।তারপরে&nbsp;&nbsp;\r\nআমরা দুপরের খাবার খাই খাবারে ছিল সমুদ্রিক মাছ।&nbsp;<o:p></o:p></span></p>', 17, 1, '2021-11-21 03:21:39', NULL);
