INSERT INTO `pages` (`id`, `page_name`, `title`, `link_canonical`, `og_locale`, `og_type`, `og_url`, `og_site_name`, `msvalidate`, `description`, `article_publisher`, `article_modified_time`, `image`, `og_image_width`, `og_image_height`, `twitter_card`, `twitter_label1`, `twitter_data1`, `google_site_verification`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Home', 'A Prominent Software Farm in Rajbari | Wake up ICT', 'https://wakeupict.com/', NULL, NULL, 'https://wakeupict.com/', NULL, NULL, '<p><strong>Wake Up ICT</strong> is a <strong>Prominent Software Farm</strong> in Rajbari. It is a complete <strong>Software Development</strong> &amp; <strong>IT Service</strong> providing Company that gives high-quality services to our customer.</p>', NULL, NULL, 'public/uploads/SEO/images/1717019285436071.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2022-01-13 01:07:24', '2022-01-13 01:07:24'),
(2, 'About', 'IT Company Rajbari Bangladesh | Wake Up ICT', 'https://wakeupict.com/about-us', NULL, NULL, NULL, NULL, NULL, '<p><strong>Wake Up ICT</strong> Academy is one of the leading IT Training Institute in Bangladesh and provides all kinds of <strong>IT-Related Solutions</strong>. Wake UP ICT has been playing a vital role in Rajbari eradicate the unemployment problem since 2015...</p>', NULL, NULL, 'public/uploads/SEO/images/1708522539636513.png', '324', '3423', NULL, NULL, NULL, NULL, '1', '2022-01-13 00:42:55', '2022-01-13 00:42:55'),
(3, 'Academic', 'Academic Training - Wake UP ICT', NULL, NULL, NULL, NULL, NULL, NULL, '<p>OUR ACADEMIC TRAINING MODULE IS THE BEST CITY &amp; WE HAVE SOME QUALIFIED TRAINERS AND A DIGITALIZED COMPUTER LAB. WE CAN ENSURE YOU THAT OUR COURSES WILL SERVE YOUR PURPOSE...</p>', NULL, '19 Aug, 2021', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-09-17 18:43:38', '2021-09-17 18:43:38'),
(4, 'Services', 'Services - Wake up ICT', NULL, NULL, NULL, NULL, NULL, NULL, '<p>The best service you can get from Wake up ICT. It is IT Training Institute in Bangladesh and provides all kinds of IT-Related Solutions.</p>', NULL, '19 Aug, 2021', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-09-20 08:11:39', '2021-09-20 08:11:39'),
(5, 'Blog', 'Our Blogs - Wake up ICT', NULL, NULL, NULL, NULL, NULL, NULL, '<p>Blogs Page Wake up ICT.</p>', NULL, '2 Sep, 2021', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-09-19 18:40:38', '2021-09-19 18:40:38'),
(6, 'Contact', 'Contact Us - Wake up ICT', 'https://wakeupict.com/contact', NULL, NULL, 'https://wakeupict.com/contact', NULL, NULL, '<p>To get a free quote, <strong>Contact us</strong> anytime with Wake up ICT.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-21 23:27:42', '2021-11-21 23:27:42'),
(14, 'গ্রাফিক্স ডিজাইন কোর্স', 'Graphic Design Course in Rajbari - Wake Up ICT', 'https://wakeupict.com/course-details/graphic-design', NULL, NULL, NULL, NULL, NULL, '<p>Graphic Design Course&nbsp;হলো এমন একটি প্রক্রিয়া যার মাধ্যমে নিজের সৃজনশীলতা ব্যবহার করে ছবি বা নকশার মাধ্যমে নিজের প্রতিভাকে প্রকাশ করা যায়। বেসিক শিখলে আমরা ছবি এডিটিং,ব্যানার তৈরি , PSD ডিজাইন, Website Template Design করতে পারব। তাই আমরা যদি Graphics Design বেসিক কোর্সটি সম্পূর্ন করতে পারি তাহলে আমরা উল্লেখিত কাজগুলো করতে পারব।<br></p>', NULL, NULL, 'public/uploads/SEO/images/1717114146469307.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 03:12:23', '2022-01-13 01:43:33'),
(15, 'ডিজিটাল মার্কেটিং কোর্স', 'ডিজিটাল মার্কেটিং', 'https://wakeupict.com/course-details/digital-marketing', NULL, NULL, 'https://wakeupict.com/course-details/digital-marketing', NULL, NULL, '<p>বর্তমান সময়ে বিজ্ঞাপনের সকল মাধ্যমগুলোর মধ্যে বর্তমান সময়ের বহুল পরিচিত এবং সবথেকে জনপ্রিয় মাধ্যম হচ্ছে&nbsp; ডিজিটাল মার্কেটিং । যেখানে অডিয়েন্স আছে কোন পণ্য বা সেবার বিজ্ঞাপন সাধারণত সাধারণভাবে সেখানেই হয়। আমরা প্রতিনিয়ত যে সব ওয়েবসাইট ব্যবহার করছি সেখানে আমরা কোন পণ্য বা সেবার বিজ্ঞাপন দিয়ে খুব সহজেই কাস্টমার দিতে পারি। মার্কেটিং এর যাবতীয় কনসেপ্ট ডিজিটাল প্লাটফর্মে প্রয়োগ করার জন্য যা জরুরী তা এখানে দেখানো হবে।<br></p>', NULL, NULL, 'public/uploads/SEO/images/1717018599812896.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-22 02:20:48', '2022-01-13 01:56:04'),
(16, 'ওয়েব ডিজাইন এন্ড ডেভেলপমেন্ট কোর্স', 'Web design and development course in Rajbari - Wake Up ICT', 'https://wakeupict.com/course-details/web-design-and-development', NULL, NULL, 'https://wakeupict.com/course-details/web-design-and-development', NULL, NULL, 'ওয়েব ডিজাইন হল একটি ওয়েবসাইটের ব্যাহিক রুপ যা আমরা দেখতে পাই বা দৃশ্য মান হয় । আর ওয়েব ডেভেলপমেন্ট হল ভেতরের সাইট যা আমরা দেখতে পাইনা । যেমন উদাহরণ সরুপ একটি গাড়ীর কথা চিন্তা করি । গাড়ির দরজা, জানালা, সিট ব্যাহিক সবকিছুই ওয়েব ডিজাইন এর মধ্যে পরে ।', NULL, NULL, 'public/uploads/SEO/images/1717115145644108.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 03:12:39', '2022-01-13 01:59:45'),
(17, 'অ্যাডভান্স গ্রাফিক ডিজাইন কোর্স', 'অ্যাডভান্স গ্রাফিক ডিজাইন', 'https://wakeupict.com/course-details/advanced-graphic-design', NULL, NULL, NULL, NULL, NULL, '<p>অ্যাডভান্সড গ্রাফিক ডিজাইন কোর্স এমন লোকদের জন্য ডিজাইন করা হয়েছে যারা গ্রাফিক ডিজাইনের সাথে পরিচিত এবং সরঞ্জাম এবং এর ব্যবহার সম্পর্কে জানেন। গ্রাফিক ডিজাইনারগণ মিডিয়া এবং ওয়েব ডিজাইন, প্যাকেজিং, চিত্রণ, অ্যানিমেশন এবং অন্যান্য ক্ষেত্রে তাদের নকশা দক্ষতা কাজে লাগান। ধারণাটি তৈরিতে সহায়ক এবং দক্ষতার সাথে প্রকল্পের সংখ্যা অন্তর্ভুক্ত করার দক্ষতাগুলি হাইলাইট করার জন্য স্তরটি উন্নত।<br></p>', NULL, NULL, 'public/uploads/SEO/images/1717115496863690.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 01:11:25', '2022-01-13 01:52:48'),
(19, 'এডভান্স ওয়েব ডিজাইন এন্ড ডেভেলপমেন্ট  কোর্স', 'অ্যাডভান্স ওয়েব ডিজাইন এবং ডেভেলপমেন্ট', 'https://wakeupict.com/course-details/advance-web-design-and-development', NULL, NULL, NULL, NULL, NULL, '<p>এডভান্স ওয়েব ডিজাইন এন্ড ডেভেলপমেন্ট হলো কোনো টেমপ্লেটকে আরও সুন্দর ভাবে সাজানো। এক্ষেত্রে HTML, CSS , CSS এর ফ্রেমওয়ার্ক Bootstrap, JavaScript এর ফ্রেমওয়ার্ক jQuery ব্যবহার করে টেমপ্লেট ডিজাইন করা হয়। ডিজাইন এর ফ্রেমওয়ার্কগুলো ব্যবহার করে টেমপ্লেট এর কোথায়, কীভাবে তথ্যগুলো দেখানো হবে সেটা নির্ধারণ করাই হলো এডভান্স ওয়েব ডিজাইনারের কাজ।<br></p>', NULL, NULL, 'public/uploads/SEO/images/1717202359256063.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 01:16:26', '2022-01-13 02:02:03'),
(45, 'ফ্রী Microsoft Office Program course', 'ফ্রী Microsoft Office Program course', 'https://wakeupict.com/blog-details/free-microsoft-office-program-course', NULL, NULL, NULL, NULL, NULL, '<p>যার ইনভাইট কার্যক্রম আমাদের পেজ এ বেশি লাইক এবং ফলোয়ার নিয়ে আসবে তাকে প্রথম বিজয়ী হিসেবে নির্ধারণ করা হবে। এবং দ্বিতীয় বিজয়ী কে লটারির মাধ্যমে নির্ধারণ করা হবে। আপনার সকল কার্যক্রম আমাদের IT Expert টিম দ্বারা মনিটরিং করা হবে সুতরাং উপরিউক্ত কোন একটি শর্তাবলী ও যদি কেউ বাদ রাখে তাহলে সে প্রতিযোগী হিসেবে গন্য হবে না।</p>', NULL, NULL, 'public/uploads/SEO/images/1717204830093531.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 01:55:42', '2021-11-23 01:55:42'),
(46, 'Microsoft Office Program course', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, NULL),
(47, 'Digital Influencers', 'Digital Influencers', 'https://wakeupict.com/blog-details/digital-influencers', NULL, NULL, NULL, NULL, NULL, '<p>Sharna Islam Zenia , one of our Digital Influencers, has successfully Communication Secrets certification from 10minuteschool. Communication also plays an essential role in human life and professional life.<br></p>', NULL, NULL, 'public/uploads/SEO/images/1717206536605035.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 02:22:50', '2021-11-23 02:22:50'),
(48, 'Sharna Islam Zenia', 'Sharna Islam Zenia Digital Influencers - Wake Up ICT', NULL, NULL, NULL, NULL, NULL, NULL, '<p><span style=\"background-color:rgb(255,255,255);color:rgb(33,37,41);\">Sharna Islam Zenia, one of our Digital Influencers, has <strong>successfully Communication Secrets</strong> certification from 10minuteschool.</span></p>', NULL, '18 Sep, 2021', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-09-17 16:21:52', '2021-09-17 16:21:52'),
(49, 'How To Improve Graphic design', 'How To Improve Graphic design', 'https://wakeupict.com/blog-details/how-to-improve-graphic-design', NULL, NULL, NULL, NULL, NULL, '<h4>Graphic design-How to improve your graphic design skills! Here are ten practical and achievable ways to help you improve your graphic design skills:<br></h4>', NULL, NULL, 'public/uploads/SEO/images/1717204275376019.png', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 02:42:13', '2021-11-23 02:42:13'),
(52, '______বিশেষ ঘোষণা______', 'ফ্রি সফ্টওয়্যার ডেভেলপমেন্ট ইন্টার্নশীপ', 'https://wakeupict.com/blog-details/free-software-development-internship', NULL, NULL, NULL, NULL, NULL, '<p><br>ফ্রি সফ্টওয়্যার ডেভেলপমেন্ট ইন্টার্নশীপ কোর্সে আবেদনের সময়সীমা বাড়ানো হয়েছে। আবেদনের সময়সীমা : ০১ সেপ্টেম্বর, ২০২১। লকডাউন পরিস্থিতি স্বাভাবিক হওয়ার কারনে খুব দ্রুত লিখিত (এমসিকিউ) পরীক্ষা নেওয়া হবে। পরীক্ষার তারিখ এবং সময় জানিয়ে দেওয়া হবে</p>', NULL, NULL, 'public/uploads/SEO/images/1717207240722975.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 02:34:01', '2021-11-23 02:34:01'),
(54, 'Nazmul Kadir', 'Nazmul Kadir Digital Influencers - Wake Up ICT', 'https://wakeupict.com/blog-details/nazmul-kadir', NULL, NULL, NULL, NULL, NULL, '<p>Nazmul Kadir, one of our Digital Influencers, has successfully achieved SEO certification from HubSpot Academy. Now he is more capable of optimizing a website to perform well in search engines.</p>', NULL, NULL, 'public/uploads/SEO/images/1717206227210351.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 02:17:54', '2021-11-23 02:17:54'),
(56, 'Md.Lotiful Azad', 'Lotiful Azad Digital Influencers - Wake Up ICT', 'https://wakeupict.com/blog-details/md.lotiful-azad', NULL, NULL, NULL, NULL, NULL, '<h2>Md.Lotiful Azad, one of our Digital Influencers, he <strong>Successfully achieved</strong> The <strong>Fundamentals of Digital Marketin</strong>g Certificate from Google. He completed the Fundamentals of Digital Marketing course and all the work required to get the certificate</h2>', NULL, NULL, 'public/uploads/SEO/images/1717206084560603.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 02:15:38', '2021-11-23 02:15:38'),
(58, 'Microsoft Office Courses Rajbari | Wake Up ICT', 'Microsoft Office - Wake UP ICT', 'https://wakeupict.com/blog-details/microsoft-office', NULL, NULL, 'https://wakeupict.com/blog-details/microsoft-office', NULL, NULL, '<p>করোনাকালীন সময়ে ঘরে বসে থেকে নিজের মূল্যবান সময় নষ্ট না করে আপনিও শিখে নিতে পারেন Microsoft Office Specialist Training Course in Rajbari- Wake UP ICT(বেসিক কম্পিউটার ট্রেনিং কোর্স)। চাকুরী, ব্যবসা সব ক্ষেত্রে Microsoft Office এর গুরুত্ব এখন অপরিসীম।</p>', NULL, NULL, 'public/uploads/SEO/images/1717205906646734.png', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 02:12:49', '2022-01-13 01:48:42'),
(60, 'How to improve your graphic', 'Graphic design', 'https://wakeupict.com/blog-details/graphic-design', NULL, NULL, NULL, NULL, NULL, '<p>We are WakeUpIct, A prominent software firm at Rajbari. We provide quality software development for different kinds of business and freelancing training to crafting professionals in minimal time.<br></p>', NULL, NULL, 'public/uploads/SEO/images/1717203651231683.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 02:44:29', '2021-11-23 02:44:29'),
(62, 'Jute Mills Project', 'Jute Mills Project Rajbari', 'https://wakeupict.com/blog-details/jute-mills-project', NULL, NULL, NULL, NULL, NULL, '<p>Rajbari Jute Mill Enterprise Resource Planning (ERP) Software is one of the biggest projects of WakeUpICT. The software development team really work very hard for crafting this software.</p>', NULL, NULL, 'public/uploads/SEO/images/1717203292818608.png', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 01:31:16', '2021-11-23 01:31:16'),
(64, 'Car Management Project', 'Car Management Project', 'https://wakeupict.com/blog-details/car-management-project', NULL, NULL, NULL, NULL, NULL, '<p>Another successful deployment of our rent a car project on Franch. Dash-Car is a company that provides rent-a-car service at Franch. Special thanks go to Folly Edem the Co-Organizer of GDG LOME for his interest in WAKEUPICT for build this project with modern technology. Finally, we complete the project and deploy it on the server.<br></p>', NULL, NULL, 'public/uploads/SEO/images/1717203183361329.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 01:29:32', '2021-11-23 01:29:32'),
(66, 'Logo Design', 'Cloud80 tech company Logo Design - Wake up ICT', 'https://wakeupict.com/blog-details/logo-design', NULL, NULL, NULL, NULL, NULL, '<p><strong>Cloud80</strong> is a <strong>tech company</strong> based in the <strong>United States</strong>, they provide Salesforce development and implementation services.</p>', NULL, NULL, 'public/uploads/SEO/images/1717202972896365.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 01:26:11', '2021-11-23 01:26:11'),
(68, 'Our Location', 'Our Location - Wake up ICT', 'https://wakeupict.com/blog-details/our-location', NULL, NULL, NULL, NULL, NULL, '<p>Wake Up ICT Academy location Nannu Tower, 3rd Floor, Panna Chattar, Rajbari.</p>', NULL, NULL, 'public/uploads/SEO/images/1717202768412209.png', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 01:22:56', '2021-11-23 01:22:56'),
(70, 'ওয়েব ডেভেলপমেন্ট ক্যারিয়ারঃ', 'কিভাবে ওয়েব ডেভেলপমেন্ট ক্যারিয়ার গড়তে পাড়ি? বিস্তারিত', 'https://wakeupict.com/blog-details/web-development-career', NULL, NULL, NULL, NULL, NULL, '<p>ওয়েব ডেভেলপমেন্ট ক্যারিয়ার বাংলাদেশের একটি অত্যন্ত সম্ভাবনাময় একটি &nbsp;ক্ষেত্র। ওয়েব ডেভেলপমেন্ট কি?এবং ক্যারিয়ার গড়তে হলে কি কি দরকার বিস্তারিত পাবেন এখানে। &nbsp;</p>', NULL, NULL, 'public/uploads/SEO/images/1717202598437461.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '1', '2021-11-23 01:20:14', '2021-11-23 01:20:14'),
